import{_ as r,a0 as a,w as i,s,ao as d,I as e,x as t,a1 as l,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/20 - The history of Android","title":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代","tag":"The history of Android","desc":""},"relativePath":"The history of Android/20 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/20 - The history of Android.md"};function m(g,o,f,y,T,A){const n=a("Link");return i(),s("div",null,[o[25]||(o[25]=d("",34)),e("p",null,[o[1]||(o[1]=t("冰淇淋三明治內置對 ",-1)),l(n,{href:"http://arstechnica.com/gadgets/2011/02/near-field-communications-a-technology-primer/"},{default:p(()=>[...o[0]||(o[0]=[t("NFC",-1)])]),_:1}),o[2]||(o[2]=t(" 的完整支持。儘管之前的設備，比如 Nexus S 也擁有 NFC，得到的支持是有限的並且系統並不能利用芯片做太多事情。4.0 添加了一個“Android Beam”功能，兩台擁有 NFC 的安卓 4.0 設備可以藉此在設備間來回傳輸數據。NFC 會傳輸關於此時屏幕顯示的數據，因此在手機顯示一個網頁的時候使用該功能會將該頁面傳送給另一部手機。你還可以發送聯繫人信息、方向導航，以及 Youtube 鏈接。當兩台手機放在一起時，屏幕顯示會縮小，點擊縮小的界面會發送相關信息。",-1))]),o[26]||(o[26]=e("p",null,"在安卓中，用户不允許刪除系統應用，以保證系統完整性。運營商和 OEM 利用該特性並開始將垃圾軟件放入系統分區，經常有一些沒用的應用存在系統中。安卓 4.0 允許用户禁用任何不能被卸載的應用，意味着該應用還存在於系統中但是不顯示在應用抽屜裏並且不能運行。如果用户願意深究設置項，這給了他們一個簡單的途徑來拿回手機的控制權。",-1)),e("p",null,[o[4]||(o[4]=t("安卓 4.0 可以看做是現代安卓時代的開始。大部分這時發佈的谷歌應用只能在安卓 4.0 及以上版本運行。4.0 還有許多谷歌想要好好利用的新 API——至少最初想要——對 4.0 以下的版本的支持就有限了。在冰淇淋三明治和蜂巢之後，谷歌真的開始認真對待軟件設計。在 2012 年 1 月，谷歌",-1)),l(n,{href:"http://arstechnica.com/business/2012/01/google-launches-style-guide-for-android-developers/"},{default:p(()=>[...o[3]||(o[3]=[t("最終發佈了",-1)])]),_:1}),o[5]||(o[5]=t()),o[6]||(o[6]=e("em",null,"Android Design",-1)),o[7]||(o[7]=t("，一個教安卓開發者如何創建符合安卓外觀和感覺的應用的設計指南站點。這是 iOS 在有第三方應用支持開始就在做的事情，蘋果還嚴肅地對待應用的設計，不符合指南的應用都被 App Store 拒之門外。安卓三年以來谷歌沒有給出任何公共設計規範文檔的事實，足以説明事情有多糟糕。但隨着在 Duarte 掌控下的安卓設計革命，谷歌終於發佈了基本設計需求。",-1))]),o[27]||(o[27]=e("h3",{id:"google-play-和直接面向消費者出售設備的迴歸",tabindex:"-1"},[t("Google Play 和直接面向消費者出售設備的迴歸 "),e("a",{class:"header-anchor",href:"#google-play-和直接面向消費者出售設備的迴歸","aria-label":"Permalink to “Google Play 和直接面向消費者出售設備的迴歸”"},"​")],-1)),o[28]||(o[28]=e("p",null,"2012 年 3 月 6 日，谷歌將旗下提供的所有內容統一到 “Google Play”。安卓市場變為了 Google Play 商店，Google Books 變為 Google Play Books，Google Music 變為 Google Play Music，還有 Android Market Movies 變為 Google Play Movies & TV。儘管應用界面的變化不是很大，這四個內容應用都獲得了新的名稱和圖標。在 Play 商店購買的內容會下載到對應的應用中，Play 商店和 Play 內容應用一道給用户提供了易管理的內容體驗。",-1)),o[29]||(o[29]=e("p",null,"Google Play 更新是谷歌第一個大的更新週期外更新。四個自帶應用都沒有通過系統更新獲得升級，它們都是直接通過安卓市場/ Play 商店更新的。對單獨的應用啓用週期外更新是谷歌的重大關注點之一，而能夠實現這樣的更新，是自薑餅時代開始的工程努力的頂峯。谷歌一直致力於對應用從系統“解耦”，從而讓它們能夠通過安卓市場/ Play 商店進行分發。",-1)),o[30]||(o[30]=e("p",null,"儘管一兩個應用（主要是地圖和 Gmail）之前就在安卓市場上，從這裏開始你會看到許多更重大的更新，而其和系統發佈無關。系統更新需要 OEM 廠商和運營商的合作，所以很難保證推送到每個用户手上。而 Play 商店更新則完全掌握在谷歌手上，給了谷歌一條直接到達用户設備的途徑。因為 Google Play 的發佈，安卓市場對自身升級到了 Google Play Store，在那之後，圖書，音樂以及電影應用都下發了 Google Play 式的更新。",-1)),o[31]||(o[31]=e("p",null,"Google Play 系列應用的設計仍然不盡相同。每個應用的外觀和功能各有差異，但暫且來説，一個統一的品牌標識是個好的開始。從品牌標識中去除“安卓”字樣是很有必要的，因為很多服務是在瀏覽器中提供的，不需要安卓設備也能使用。",-1)),e("p",null,[o[9]||(o[9]=t("2012 年 4 月，谷歌",-1)),l(n,{href:"http://arstechnica.com/gadgets/2011/02/near-field-communications-a-technology-primer/"},{default:p(()=>[...o[8]||(o[8]=[t("再次開始通過 Play 商店銷售設備",-1)])]),_:1}),o[10]||(o[10]=t("，恢復在 Nexus One 發佈時嘗試的直接面向消費者銷售的方式。儘管距 Nexus One 銷售結束僅有兩年，但網上購物現在更加尋常，在接觸到物品之前就購買它並不像在 2010 年時聽起來那麼瘋狂。",-1))]),o[32]||(o[32]=e("p",null,"谷歌也看到了價格敏感的用户在面對 Nexus One 的 530 美元的價格時的反應。第一部銷售的設備是無鎖的，GSM 版本的 Galaxy Nexus，價格 399 美元。在那之後，價格變得更低。350 美元成為了最近兩台 Nexus 設備的入門價，7 英寸 Nexus 平板的價格更是隻有 200 美元到 220 美元。",-1)),o[33]||(o[33]=e("p",null,"今天，Play 商店銷售八款不同的安卓設備，四款 Chromebook，一款自動調温器，以及許多配件，設備商店已經是谷歌新產品發佈的實際地點了。新產品發佈總是如此受歡迎，站點往往無法承載如此大的流量，新 Nexus 手機也在幾小時內售空。",-1)),o[34]||(o[34]=e("hr",null,null,-1)),o[35]||(o[35]=e("p",null,[e("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg",alt:"Ron Amadeo"})],-1)),e("p",null,[l(n,{href:"http://arstechnica.com/author/ronamadeo"},{default:p(()=>[...o[11]||(o[11]=[t("Ron Amadeo",-1)])]),_:1}),o[13]||(o[13]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),l(n,{href:"https://twitter.com/RonAmadeo"},{default:p(()=>[...o[12]||(o[12]=[t("@RonAmadeo",-1)])]),_:1})]),o[36]||(o[36]=e("hr",null,null,-1)),e("p",null,[o[15]||(o[15]=t("via: ",-1)),l(n,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/20/"},{default:p(()=>[...o[14]||(o[14]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/20/",-1)])]),_:1})]),e("p",null,[o[18]||(o[18]=t("譯者：",-1)),l(n,{href:"https://github.com/alim0x"},{default:p(()=>[...o[16]||(o[16]=[t("alim0x",-1)])]),_:1}),o[19]||(o[19]=t(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:p(()=>[...o[17]||(o[17]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[22]||(o[22]=t("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...o[20]||(o[20]=[t("LCTT",-1)])]),_:1}),o[23]||(o[23]=t(" 原創翻譯，",-1)),l(n,{href:"http://linux.cn/"},{default:p(()=>[...o[21]||(o[21]=[t("Linux中國",-1)])]),_:1}),o[24]||(o[24]=t(" 榮譽推出",-1))])])}const b=r(u,[["render",m]]);export{x as __pageData,b as default};
